package com.catalogix.audit.controller; import com.catalogix.audit.dto.AuditResponse; import com.catalogix.audit.repository.AuditRepository; import org.springframework.data.domain.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/audit") public class AuditController{final AuditRepository repo;public AuditController(AuditRepository r){repo=r;}@GetMapping public Page<AuditResponse> list(@RequestAttribute String userRole,@PageableDefault(size=30)Pageable p){if(!"ADMIN".equalsIgnoreCase(userRole))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN,"Admin role required");return repo.findAllByOrderByOccurredAtDesc(p).map(e->new AuditResponse(e.getId(),e.getActorUserId(),e.getAction(),e.getEntityType(),e.getEntityId(),e.getDetails(),e.getOccurredAt()));}}
